typedef struct TestResults
{
    unsigned int passed;
    unsigned int failed;

} TestResults;

static void test_check(TestResults* results, sfBool condition, const char* message)
{
    if (condition)
    {
        ++results->passed;
        printf("[PASS] %s\n", message);
        return;
    }

    ++results->failed;
    printf("[FAIL] %s\n", message);
}

static const char* mainMenuAction_toString(MainMenuAction action)
{
    switch (action)
    {
        case mainMenuActionNone:
            return "None";

        case mainMenuActionPlay:
            return "Play";

        case mainMenuActionSettings:
            return "Settings";

        case mainMenuActionCredits:
            return "Credits";

        case mainMenuActionExit:
            return "Exit";

        default:
            return "Unknown";
    }
}

